const CYCLE = 100;
const COLS = createCols("https://coolors.co/ea781a-6e43db-24e5a5-fafafa");
let bgCol = COLS[0];
let cubes = [];
let gra;



function setup() {
	createCanvas(windowWidth, windowHeight,WEBGL);

	//ortho
	let dep = max(width,height);
	ortho(-width / 2, width / 2, -height / 2, height / 2,-dep*3 , dep*3);
	noStroke();

	//init
	let span = 120;
	let spanY = span *  sqrt(3)/2;
	let countY = 0;
	for(let y = -height/2; y < height/2 + spanY; y += (Math.max(0.001, Math.abs(spanY)) || 1))
	{
		let offX = countY % 2 == 0 ? 0 : span /2;
		for(let x = -width/2 - offX; x < width/2 + span; x += (Math.max(0.001, Math.abs(span)) || 1))
		{
			cubes.push(new MovingCube(createVector(x,y,0), createVector(0,0,0), span / sqrt(2) + 0.5));
		}
		countY ++ ;
	}

	//gra
	gra = createGraphics(width, height);
	gra.background(255,0);
  gra.noStroke();
  for (let i = 0; i < 300000; i++) {
    let x = random(width);
    let y = random(height);
    let s = noise(x*0.01, y*0.01)*width*0.0015;
    gra.fill(255,20);
    gra.rect(x, y, s, s);
  } 

}

function draw() {
	if(frameCount % (CYCLE * 2) == CYCLE)bgCol = random(COLS);
	background(bgCol);

	for(const c of cubes)
	{
		c.update();
		c.display();
	}

	push();
	translate(-width/2,-height/2,height);
	image(gra,0,0);
	pop();
}


class MovingCube
{
	constructor(pos, rotation,size)
	{
		this.rotScledule = [createVector(0,0,0),createVector(-PI/6,PI/4,0),
												createVector(0,PI/2,0),createVector(PI/6,PI/4 * 3,0),
												createVector(0,PI,0)];
		this.pos = pos;
		this.rotation = rotation;
		this.size = size;
		this.count = 0;
		this.cycleOffset = floor(random(100)) * 2;
		this.rotateOffset = random() > 0.5 ?  HALF_PI : 0;
	}

	update()
	{
		const cycleCount = floor(this.count / CYCLE) + this.cycleOffset;
		const rotIndex = cycleCount % (this.rotScledule.length -1);
		const startRot = this.rotScledule[rotIndex];
		const targetRot = this.rotScledule[rotIndex + 1];

		const cycleRatio = (this.count % CYCLE ) / CYCLE;
		const rotateRatio = min(cycleRatio * 1.4, 1);
		const rotationRatioEased = easeInOutBack(rotateRatio);
		const currentRotation = p5.Vector.lerp(startRot, targetRot, rotationRatioEased);
		this.rotation = currentRotation;

		this.count++;
	}

	display()
	{
		push();
		translate(this.pos);

		rotateX(this.rotation.x);
		rotateY(this.rotation.y);
		rotateZ(this.rotation.z);
		rotateZ(this.rotateOffset );

		cube(this.size);
		pop();
	}
}


function cube(size, cols = COLS)
{
	if(cols.length < 3)return;
	fill(cols[0]);
	push();
	translate(0, 0, size/2);
	plane(size,size);
	translate(0, 0, -size);
	rotateY(PI);
	plane(size,size);
	pop();

	fill(cols[1]);
	push();
	translate(0, -size/2, 0);
	rotateX(PI/2);
	plane(size,size);
	translate(0, 0, -size);
	rotateX(PI);
	plane(size,size);
	pop();

	fill(cols[2]);
	push();
	translate(size/2, 0, 0);
	rotateY(PI/2);
	plane(size,size);
	translate(0, 0, -size);
	rotateX(PI);
	plane(size,size);
	pop();
}


function createCols(_url)
{
  let slash_index = _url.lastIndexOf('/');
  let pallate_str = _url.slice(slash_index + 1);
  let arr = pallate_str.split('-');
  for (let i = 0; i < arr.length; i++) {
    arr[i] = '#' + arr[i];
  }
  return arr;
}


function easeInOutBack(x) {
const c1 = 1.70158;
const c2 = c1 * 1.525;

return x < 0.5
  ? (pow(2 * x, 2) * ((c2 + 1) * 2 * x - c2)) / 2
  : (pow(2 * x - 2, 2) * ((c2 + 1) * (x * 2 - 2) + c2) + 2) / 2;
}


// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
